insert into contingencias (proyecto_id, caso, que_dice, a_cargo_de, fuente, orden) values
  ('pry-1', 'mortandad', 'Hasta el 2 % del lote lo absorbe el fideicomiso. Por encima de ese piso responde el productor, salvo caso fortuito acreditado.', 'Fideicomiso hasta el piso; después, el productor', 'demostrativo', 0),
  ('pry-1', 'sanitaria', 'El productor avisa dentro de las 48 horas, aísla el lote y carga el diagnóstico. El tratamiento sale del rubro de sanidad del presupuesto aprobado.', 'Presupuesto del proyecto', 'demostrativo', 1),
